/**
 * generated by stackra gen from src/config/seo.config.ts (sitemapPageSize),
 * src/config/i18n.config.ts (locales), gen/sitemap.ts, src/routes/site/site.layout.ts and
 * context.ts — do not edit
 * Purpose: `/sitemaps/<source>-<page>.xml`: one page of one source's URLs, each with hreflang
 *          alternates for every locale and image entries where the source provides them. Page 1
 *          of an empty source is a valid empty sitemap; a page past the end is 404.
 * Boundary: alternates come from the same `@stackra/seo` function the route adapters use for every
 *           head (an ordinary function, callable from client and server code), so links and
 *           sitemaps never disagree.
 * Runtime: worker
 */
import { routeContext } from "@stackra/navigation/router";
import { alternates, SeoConfig } from "@stackra/seo";
import { sitemapPage, writeSitemap } from "@stackra/seo/sitemap";
import type { Route } from "./+types/sitemap";
import { SiteLayout } from "#src/routes/site/site.layout";
import { sitemapSources } from "#stackra/sitemap";
import { routeKeys } from "../context";

/** `products-2.xml` → `{ source: "products", page: 2 }`. */
const FILE = /^(?<source>[a-z_]+)-(?<page>[1-9]\d{0,5})\.xml$/;

/** One page of one source, or 404 for an unknown source, a page past the end or a hidden site. */
export async function loader(args: Route.LoaderArgs) {
  const ctx = routeContext(args, routeKeys);
  const match = FILE.exec(args.params.file);
  // own properties only: an inherited name such as `constructor` or `__proto__` is not a source
  const name = match?.groups?.source;
  const source = name && Object.hasOwn(sitemapSources, name) ? sitemapSources[name] : undefined;
  const { site } = await ctx.layout(SiteLayout);
  if (!match?.groups || !source || !site.indexable) return new Response(null, { status: 404 });
  const page = Number(match.groups.page);
  const items = await sitemapPage(source, {
    clients: ctx.clients,
    site,
    href: ctx.href,
    page,
    pageSize: ctx.config(SeoConfig).sitemapPageSize,
  });
  if (items === null) return new Response(null, { status: 404 }); // past the last page
  const entries = items.map((item) => {
    const urls = alternates(ctx, item.path);
    return {
      loc: urls["x-default"],
      lastmod: item.updatedAt,
      changefreq: source.changefreq,
      alternates: urls,
      images: item.image ? [item.image] : [],
    };
  });
  return new Response(writeSitemap(entries), {
    headers: {
      "Content-Type": "application/xml; charset=utf-8",
      "Cache-Control": "public, max-age=3600",
    },
  });
}
